def format_bytes(n):
    """Return a human-readable representation of a byte size, e.g. '1.5 KB'."""
    unit = 'B'
    value = float(n)
    for u in ['B', 'KB', 'MB', 'GB', 'TB', 'PB']:
        if value < 1024 or u == 'PB':
            if u == 'B':
                return f'{int(value)} {u}'
            return f'{value:.1f} {u}'
        value /= 1024
    return f'{value:.1f} PB'
